import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    total_cpu = 0.0
    total_memory = 0
    start_time = time.time()

    process = subprocess.Popen(['bash', script_path], shell=True)

    try:
        ps_process = psutil.Process(process.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    while True:
        if process.poll() is not None:
            break

        if time.time() - start_time > timeout:
            process.terminate()
            try:
                process.wait(timeout=2)
            except subprocess.TimeoutExpired:
                process.kill()
            break

        try:
            cpu_percent = ps_process.cpu_percent(interval=0)
            mem_info = ps_process.memory_info()
            total_cpu += cpu_percent
            total_memory += mem_info.rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break

        time.sleep(0.1)

    return {'CPU Usage': total_cpu, 'Memory Usage': total_memory}
